// Bloodright Jutsu Reference Library capture batches (push/102, push/103), generated by
// scripts/bloodright_reference.py manifests. Socket-free: each parses under Forge's own parser,
// plans zero items, carries only jutsu.get / bloodline.get persist:"full" point reads, and runs
// against an in-process fake game with no procedure other than those reads.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parseManifest, planOrder } from "../src/runner/manifest.mjs";
import { FakeGame } from "./fakegame.mjs";
import { MemoryStorage } from "./shim.mjs";
import { composeForTest } from "./compose.mjs";

const BATCHES = [
  ["../../push/102_bloodright_reference_capture_batch_1.json", "36edd88f", 97],
  ["../../push/103_bloodright_reference_capture_batch_2.json", "3ee2949b", 91],
];

for (const [rel, hash, reads] of BATCHES) {
  const raw = () => JSON.parse(readFileSync(new URL(rel, import.meta.url), "utf8"));

  test(`${rel.split("/").pop()} is a capture-only job of ${reads} full point reads`, () => {
    const m = parseManifest(JSON.stringify(raw()));
    assert.equal(m.hash, hash);
    assert.equal(planOrder(m).length, 0);
    assert.equal(m.fullCaptures, reads);
    for (const c of raw().capture.before) {
      assert.ok(c.proc === "jutsu.get" || c.proc === "bloodline.get");
      assert.deepEqual(Object.keys(c.input), ["id"]);
    }
  });

  test(`${rel.split("/").pop()} runs read-only against a fake game`, async () => {
    const game = new FakeGame();
    const storage = new MemoryStorage();
    for (const c of raw().capture.before) {
      game.seed(c.proc === "jutsu.get" ? "jutsu" : "bloodline", { id: c.input.id, name: c.input.id, image: `https://utfs.io/f/${c.input.id}` });
    }
    const d = composeForTest({ game, storage });
    d.runner.plan(raw(), { jobId: "b", manifestPath: rel.replace("../../", "") });
    const s = await d.runner.run("b");
    assert.equal(s.state, "DONE");
    assert.equal(s.outcome, "success");
    assert.ok(game.calls.every((c) => c.path === "jutsu.get" || c.path === "bloodline.get"));
  });
}
